SELECT CASE WHEN EXISTS (
SELECT 1
  FROM "holidays"
 WHERE "del_flag"         = 0
   AND "business_corp_id" = #{businessCorpId}
   AND "holiday_date"     = CAST(#{targetDate} AS date)
) THEN '1' ELSE '0' END AS exists_flag;

 SELECT CASE WHEN EXISTS (
 SELECT 1
 FROM "calendar_details"
 WHERE "del_flag"      = 0
   AND "calendar_id"   = #{calendarId}
   AND "day_week_type" = #{dayWeekType}
) THEN '1' ELSE '0' END AS exists_flag;

